   "vars": {"mejor_evaluado": "$s2.mejor_evaluado", "mas_barato": "$s2.mas_barato", "id0": "$s1.0.id", "id1": "$s1.1.id", "id2": "$s1.2.id", "resumen_reviews": "$s3"}}
